def longest_k_distinct(s: str, k: int) -> int:
    count = {}
    start = best = 0
    for i, ch in enumerate(s):
        count[ch] = count.get(ch, 0) + 1
        while len(count) > k:
            count[s[start]] -= 1
            if count[s[start]] == 0:
                del count[s[start]]
            start += 1
        best = max(best, i - start + 1)
    return best

