#include <bits/stdc++.h>
using namespace std;

int kDistinctChars(int k, string& s) {
    unordered_map<char, int> count;
    int start = 0, ans = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        ++count[s[i]];
        while ((int)count.size() > k) {
            if (--count[s[start]] == 0) count.erase(s[start]);
            ++start;
        }
        ans = max(ans, i - start + 1);
    }
    return ans;
}

